<script setup lang="ts">
const props=defineProps<{kind:'cyclecount'|'adjustment'}>()
const {t}=useI18n(),route=useRoute(),router=useRouter(),staff=useStaffStore(),warehouse=useWarehouseStore(),{bizErrorMessage}=useBizError()
const data=ref<PaginationData|null>(null),loading=ref(false),error=ref(''),keyword=ref(String(route.query.keyword||'')),counts=ref<Record<string,number>>({})
const statuses=computed(()=>props.kind==='cyclecount'?['all','pending','in_progress','completed']:['all','pending','approved','completed','cancelled'])
const permissionPrefix=computed(()=>props.kind==='cyclecount'?'cycle_count':'adjustment')
const ready=computed(()=>staff.refreshed&&!!staff.staffInfo)
const canRead=computed(()=>ready.value&&staff.hasPermission(permissionPrefix.value+'_read'))
const canApprove=computed(()=>ready.value&&staff.hasPermission('adjustment_approve'))
const awaitingMine=computed(()=>props.kind==='adjustment'&&canApprove.value&&route.query.awaiting_my_approval==='true')
const creatorId=computed({get:()=>route.query.created_by?Number(route.query.created_by):null,set:value=>go({created_by:value})})
const creatorLabel=computed(()=>{const id=creatorId.value;if(!id)return '';const row=data.value?.items.find((row:any)=>Number(row.created_by)===id);return row?.creator?.user_name||(id===staff.staffInfo?.id?staff.staffInfo.user_name:t('common.users.user-ref',{id}))})
const searchCreators=async(query:string)=>{
 if(!ready.value||!staff.hasPermission('staff_read'))return []
 const responses=await Promise.all([true,false].map(is_active=>httpRequest<PaginationData>('/api/warehouse/staff/',{params:{keyword:query,is_active,per_page:50,page:1},headers:warehouseHeaders(warehouse.currentWarehouse?.id),onError:e=>showToast(bizErrorMessage(e),'error')})))
 const users=[...(data.value?.items||[]).map((row:any)=>row.creator),...responses.flatMap(response=>response?.items||[])].filter((user:any)=>user?.id&&String(user.user_name).toLowerCase().includes(query.toLowerCase()))
 return Array.from(new Map(users.map((user:any)=>[user.id,{value:Number(user.id),label:user.user_name}])).values())
}
const canProcess=(row:any)=>{
 if(!ready.value||row.is_active===false||row.status==='completed')return false
 if(props.kind==='cyclecount')return staff.hasPermission('cycle_count_execute','cycle_count_edit')
 if(row.status==='approved')return staff.hasPermission('adjustment_edit')
 return row.status==='pending'&&canApprove.value&&Number(row.created_by)!==staff.staffInfo?.id&&Number(row.details_modified_by)!==staff.staffInfo?.id
}
const deleting=ref(false)
const prefix=computed(()=>props.kind==='cyclecount'?'CC':'ADJ')
const active=computed(()=>route.query.is_active==='false'?'cancelled':String(route.query.status||'all')),page=computed(()=>Number(route.query.page)||1)
const tabs=computed(()=>statuses.value.map(key=>({key,label:t('common.status.'+key.replaceAll('_','-')),count:counts.value[key]})))
const filterFor=(status:string)=>status==='cancelled'?{status:undefined,is_active:false}:{status:status==='all'?undefined:status,is_active:true}
const switchTab=(value:any)=>go(filterFor(String(value)))
const adjustmentReasonLabel=(value:unknown)=>{const text=String(value||'—'),match=/^Adjustment by CycleCountTask ID:\s*(\d+)$/.exec(text);return match?t('adjustment.tips.from-cyclecount',{id:match[1]}):text}
const go=(patch:Record<string,any>,keepPage=false)=>{const query:Record<string,any>={...route.query,...patch};if(!keepPage)delete query.page;for(const key of Object.keys(query))if(query[key]==null||query[key]===''||query[key]==='all')delete query[key];router.push({query})}
let previousWarehouseScope=String(warehouse.currentWarehouse?.id??useCookie('warehouse_id').value??'')
let generation=0
const load=async()=>{
 const seq=++generation;loading.value=true;error.value='';data.value=null;counts.value={}
 if(!canRead.value){loading.value=false;return}
 const headers=warehouseHeaders(warehouse.currentWarehouse?.id),base={...route.query,warehouse_id:warehouse.currentWarehouse?.id,awaiting_my_approval:awaitingMine.value?true:undefined}
 const results=await Promise.all([httpRequest<PaginationData>('/api/warehouse/'+props.kind+'/',{params:{...base,per_page:20,page:page.value},headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}),...statuses.value.map(status=>httpRequest<PaginationData>('/api/warehouse/'+props.kind+'/',{params:{...base,...filterFor(status),page:1,per_page:1},headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}))])
 if(seq!==generation)return
 data.value=results[0]||null;loading.value=false
 statuses.value.forEach((status,index)=>{const value=results[index+1];if(value)counts.value[status]=value.total})
}
const counted=(row:any)=>Number(row.recorded_count||0)
const variance=(row:any)=>Number(row.variance_count||0)
const columns=computed(()=>props.kind==='cyclecount'?[
 {key:'task',label:t('cyclecount.entity')},{key:'scope',label:t('operations.ui.scope')},{key:'planned',label:t('cyclecount.fields.scheduled-date')},{key:'progress',label:t('operations.ui.progress')},{key:'variance',label:t('operations.ui.variance')},{key:'next',label:t('operations.ui.next'),align:'right' as const}
]:[{key:'task',label:t('adjustment.entity')},{key:'reason',label:t('adjustment.fields.reason')},{key:'scope',label:t('common.fields.items')},{key:'status',label:t('common.fields.status')},{key:'operator',label:t('operations.ui.time-operator')},{key:'next',label:t('operations.ui.next'),align:'right' as const}])
const deleteTask=async(row:any)=>{
 if(deleting.value||!ready.value||!staff.hasPermission(permissionPrefix.value+'_delete'))return
 deleting.value=true
 try{
  if(!await wConfirm({title:t('action-results.delete-confirm-title'),message:t('action-results.delete-confirm',{entity:prefix.value+'-'+row.id}),confirmText:t('button.delete'),cancelText:t('button.cancel')}))return
  let success=false
  await httpRequest('/api/warehouse/'+props.kind+'/'+row.id,{method:'DELETE',headers:warehouseHeaders(row.warehouse_id),onSuccess:()=>success=true,onError:e=>showToast(bizErrorMessage(e),'error')})
  if(success)await load()
 }finally{deleting.value=false}
}

watch(()=>route.query,()=>{keyword.value=String(route.query.keyword||'');load()});watch(canRead,load);watch(()=>warehouse.currentWarehouse?.id,id=>{const scope=String(id??'');const changed=scope!==previousWarehouseScope;previousWarehouseScope=scope;if(changed&&route.query.page&&Number(route.query.page)!==1)go({page:1});else load()});onMounted(load);onBeforeUnmount(()=>generation++)
useHead({title:()=>t('nav.'+props.kind)})
</script>
<template><div class="w-task-list w-scope"><header><h1>{{t('nav.'+kind)}}</h1><span>{{data?.total}}</span><WButton v-if="ready&&staff.hasPermission(permissionPrefix+'_edit')" class="w-inventory-create" variant="primary" icon="plus" :to="'/'+kind+'/add'">{{t(kind+'.operations.add')}}</WButton></header><WCard flush><WTabs inset :items="tabs" :model-value="active" :label="t('common.fields.status')" @update:model-value="switchTab" /><form class="w-task-filters" @submit.prevent="go({keyword:keyword.trim()})"><WInput v-model="keyword" type="search" :aria-label="t('common.search')" :placeholder="t('inventory-task-list.search-'+kind)" @change="go({keyword:keyword.trim()})"><template #prefix><WIcon name="search" :size="16" /></template></WInput><template v-if="kind==='adjustment'"><WSelect :model-value="String(route.query.source||'')" :aria-label="t('inventory-task-list.source')" :options="[{value:'',label:t('inventory-task-list.source')+' · '+t('common.status.all')},{value:'manual',label:t('inventory-task-list.manual')},{value:'cyclecount',label:t('nav.cyclecount')}]" @update:model-value="value=>go({source:value})"/><WCombobox v-if="ready&&staff.hasPermission('staff_read')" v-model="creatorId" :search="searchCreators" :selected-label="creatorLabel" :aria-label="t('common.users.creator')" :placeholder="t('common.users.creator')" clearable/></template><template v-else><WField :label="t('inventory-task-list.start')"><WDatePicker :model-value="String(route.query.scheduled_start_date||'')" :max="String(route.query.scheduled_end_date||'')" :aria-label="t('inventory-task-list.start')" clearable @update:model-value="value=>go({scheduled_start_date:value,scheduled_date:undefined})"/></WField><WField :label="t('inventory-task-list.end')"><WDatePicker :model-value="String(route.query.scheduled_end_date||'')" :min="String(route.query.scheduled_start_date||'')" :aria-label="t('inventory-task-list.end')" clearable @update:model-value="value=>go({scheduled_end_date:value,scheduled_date:undefined})"/></WField><WButton :aria-pressed="route.query.has_variance==='true'" :variant="route.query.has_variance==='true'?'primary':'secondary'" @click="go({has_variance:route.query.has_variance==='true'?undefined:'true'})">{{t('inventory-task-list.has-variance')}}</WButton></template><WButton v-if="kind==='adjustment'&&canApprove" :variant="awaitingMine?'primary':'secondary'" :aria-pressed="awaitingMine" @click="go({awaiting_my_approval:awaitingMine?undefined:'true',status:undefined,is_active:undefined})">{{t('inventory-task-list.awaiting-mine')}}</WButton></form><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><WTable :rows="data?.items||[]" :columns="columns" :loading="loading" inset><template #cell-task="{row}"><NuxtLink class="w-task-name" :to="'/'+kind+'/detail/'+row.id">{{prefix}}-{{row.id}}</NuxtLink><span class="w-task-sub">{{row.task_name||row.warehouse?.name}}</span></template><template #cell-scope="{row}"><strong>{{row.goods_count??row.detail_count}}</strong><span class="w-task-sub">{{kind==='cyclecount'?t('inventory-task-list.scope',{lines:row.detail_count,locations:row.location_count??'—'}):t('inventory-task-list.lines',{count:row.detail_count})}}</span><span v-if="row.lot_numbers?.length" class="w-task-sub">{{row.lot_numbers.join(' · ')}}</span><span v-if="kind==='adjustment'&&(row.increase_quantity||row.decrease_quantity)" class="w-task-sub">+{{row.increase_quantity}} / −{{row.decrease_quantity}}</span><span class="w-task-sub">{{row.warehouse?.name}}</span></template><template #cell-planned="{row}">{{row.scheduled_date?$dayjs(row.scheduled_date,'YYYY-MM-DD',row):'—'}}<span class="w-task-sub">{{row.creator?.user_name}}</span></template><template #cell-progress="{row}"><WStatus :tone="row.status==='completed'?'ok':row.status==='in_progress'?'warn':'none'">{{t('common.status.'+row.status.replaceAll('_','-'))}}</WStatus><span v-if="row.recorded_count!=null" class="w-task-sub">{{counted(row)}} / {{row.detail_count}}</span><progress v-if="row.recorded_count!=null" class="w-count-progress" :class="{'is-completed':row.status==='completed'}" :value="counted(row)" :max="Math.max(row.detail_count,1)" :aria-label="t('operations.ui.progress')" /></template><template #cell-variance="{row}"><span v-if="row.recorded_count!=null&&counted(row)">{{t('inventory-task-list.variance-lines',{count:variance(row)})}}</span><span v-else>—</span></template><template #cell-reason="{row}">{{adjustmentReasonLabel(row.adjustment_reason)}}<NuxtLink v-if="row.cyclecount_id&&staff.hasPermission('cycle_count_read')" class="w-task-sub" :to="'/cyclecount/detail/'+row.cyclecount_id">CC-{{row.cyclecount_id}}</NuxtLink><span v-else-if="row.cyclecount_id" class="w-task-sub">CC-{{row.cyclecount_id}}</span></template><template #cell-status="{row}"><WStatus :tone="row.is_active===false?'none':row.status==='completed'?'ok':'warn'">{{t('common.status.'+(row.is_active===false?'cancelled':row.status))}}</WStatus></template><template #cell-operator="{row}">{{row.operator?.user_name||row.approver?.user_name||row.creator?.user_name||'—'}}<span class="w-task-sub">{{$dayjs(row.updated_at,'MM/DD HH:mm',row)}}</span></template><template #cell-next="{row}"><div class="w-task-actions"><WButton size="sm" :to="'/'+kind+'/detail/'+row.id">{{t(!canProcess(row)||row.status==='completed'||row.is_active===false?'operations.ui.view':'operations.ui.process')}}</WButton><WButton v-if="row.status==='pending'&&row.is_active!==false&&ready&&staff.hasPermission(permissionPrefix+'_delete')" size="sm" variant="text" icon="trash" icon-only :aria-label="t('button.delete')" :disabled="deleting" @click="deleteTask(row)" /></div></template></WTable><footer><WPagination :page="page" :page-size="20" :total="data?.total" show-total @update:page="value=>go({page:value},true)" /></footer></WCard></div></template>
<style scoped>
.w-task-list{display:flex;flex-direction:column;gap:16px}.w-task-list header{display:flex;flex-wrap:wrap;gap:12px;align-items:baseline}.w-task-list h1{margin:0;font-size:24px;line-height:32px;font-weight:600}.w-task-list header>span{font-size:13px;color:var(--w-text-2)}.w-task-filters{display:flex;flex-wrap:wrap;gap:12px;padding:12px 20px;border-bottom:1px solid var(--w-line)}.w-task-filters>.w-input{width:360px;max-width:100%}.w-task-list :deep(.w-table){min-width:900px}.w-task-list :deep(.w-table-wrap.is-inset){--w-table-edge:20px}.w-task-list :deep(.w-table th){height:auto;padding-top:10px;padding-bottom:8px;line-height:16px}.w-task-list :deep(.w-table td){padding-top:12px;padding-bottom:12px;vertical-align:top}.w-task-name{display:block;font-size:14px;line-height:20px;font-weight:500;color:var(--w-text-1);text-decoration:none;margin-bottom:4px}.w-task-link{font-size:13px;color:var(--w-link);text-decoration:none}.w-task-sub{display:block;font-size:12px;line-height:18px;color:var(--w-text-3);margin-top:4px}.w-task-progress{display:flex;flex-direction:column;gap:8px;min-width:120px;max-width:180px}.w-task-progress strong{font-size:14px;font-weight:600}.w-task-progress strong span{color:var(--w-text-3);font-weight:400}.w-task-progress progress{width:100%;height:4px;border:0;border-radius:4px;overflow:hidden;background:#EDEFF3}.w-task-progress progress::-webkit-progress-bar{background:#EDEFF3}.w-task-progress progress::-webkit-progress-value{background:#5F1FE6}.w-task-list footer{padding:12px 20px;border-top:1px solid var(--w-border)}
</style>

<style scoped>.w-inventory-create{margin-left:auto}.w-task-actions{display:flex;justify-content:flex-end;gap:4px}.w-count-progress{display:block;width:100px;height:4px;margin-top:6px;border:0;border-radius:4px;overflow:hidden;background:var(--w-line);appearance:none}.w-count-progress::-webkit-progress-bar{background:var(--w-line)}.w-count-progress::-webkit-progress-value{background:var(--w-pri)}.w-count-progress::-moz-progress-bar{background:var(--w-pri)}</style>

<style scoped>.w-task-sub{overflow-wrap:anywhere;white-space:normal;max-width:260px}.w-task-list :deep(.w-table td){max-width:300px;white-space:normal;overflow-wrap:anywhere}.w-task-actions{white-space:nowrap}</style>

<style scoped>.w-task-filters :deep(.w-combo){width:180px;max-width:100%}.w-task-filters :deep(.w-select){width:160px;max-width:100%}.w-task-filters :deep(.w-date-picker){max-width:100%}</style>

<style scoped>.w-task-filters{align-items:flex-end}.w-task-filters>.w-field{width:180px;max-width:100%}</style>

<style scoped>.w-count-progress.is-completed::-webkit-progress-value{background:var(--w-text-3)}.w-count-progress.is-completed::-moz-progress-bar{background:var(--w-text-3)}</style>
